377	  private:
378	
379	#if JSON_DIAGNOSTIC_POSITIONS
380	    void handle_diagnostic_positions_for_json_value(BasicJsonType& v)
381	    {
382	        if (m_lexer_ref)
383	        {
384	            // Lexer has read past the current field value, so set the end position to the current position.
385	            // The start position will be set below based on the length of the string representation
386	            // of the value.
387	            v.end_position = m_lexer_ref->get_position();
388	
389	            switch (v.type())
390	            {
391	                case value_t::boolean:
392	                {
393	                    // 4 and 5 are the string length of "true" and "false"
394	                    v.start_position = v.end_position - (v.m_data.m_value.boolean ? 4 : 5);
395	                    break;
396	                }
397	
398	                case value_t::null:
399	                {
400	                    // 4 is the string length of "null"
401	                    v.start_position = v.end_position - 4;
402	                    break;
403	                }
404	
405	                case value_t::string:
406	                {
407	                    // escape sequences make the token longer than the value it
408	                    // parses to, so the start position cannot be derived from
409	                    // the value; use the offset the lexer recorded instead
410	                    v.start_position = m_lexer_ref->get_token_start_position();
411	                    break;
412	                }
413	
414	                // As we handle the start and end positions for values created during parsing,
415	                // we do not expect the following value type to be called. Regardless, set the positions
416	                // in case this is created manually or through a different constructor. Exclude from lcov
417	                // since the exact condition of this switch is esoteric.
418	                // LCOV_EXCL_START
419	                case value_t::discarded:
420	                {
421	                    v.end_position = std::string::npos;
422	                    v.start_position = v.end_position;
423	                    break;
424	                }
425	                // LCOV_EXCL_STOP
426	                case value_t::binary:
427	                case value_t::number_integer:
428	                case value_t::number_unsigned:
429	                case value_t::number_float:
430	                {
431	                    v.start_position = v.end_position - m_lexer_ref->get_string().size();
432	                    break;
433	                }
434	                case value_t::object:
435	                case value_t::array:
436	                {
437	                    // object and array are handled in start_object() and start_array() handlers
438	                    // skip setting the values here.
439	                    break;
440	                }
441	                default: // LCOV_EXCL_LINE
442	                    // Handle all possible types discretely, default handler should never be reached.
443	                    JSON_ASSERT(false); // NOLINT(cert-dcl03-c,hicpp-static-assert,misc-static-assert,-warnings-as-errors) LCOV_EXCL_LINE
444	            }
445	        }
446	    }
447	#endif
