449	    /*!
450	    @invariant If the ref stack is empty, then the passed value will be the new
451	               root.
452	    @invariant If the ref stack contains a value, then it is an array or an
453	               object to which we can add elements
454	    */
455	    template<typename Value>
456	    JSON_HEDLEY_RETURNS_NON_NULL
457	    BasicJsonType* handle_value(Value&& v)
458	    {
459	        if (ref_stack.empty())
460	        {
461	            root = BasicJsonType(std::forward<Value>(v));
462	
463	#if JSON_DIAGNOSTIC_POSITIONS
464	            handle_diagnostic_positions_for_json_value(root);
465	#endif
466	
467	            return &root;
468	        }
469	
470	        JSON_ASSERT(ref_stack.back()->is_array() || ref_stack.back()->is_object());
471	
472	        if (ref_stack.back()->is_array())
473	        {
474	            ref_stack.back()->m_data.m_value.array->emplace_back(std::forward<Value>(v));
475	
476	#if JSON_DIAGNOSTIC_POSITIONS
477	            handle_diagnostic_positions_for_json_value(ref_stack.back()->m_data.m_value.array->back());
478	#endif
479	
480	            return &(ref_stack.back()->m_data.m_value.array->back());
481	        }
482	
483	        JSON_ASSERT(ref_stack.back()->is_object());
484	        JSON_ASSERT(object_element);
485	        *object_element = BasicJsonType(std::forward<Value>(v));
486	
487	#if JSON_DIAGNOSTIC_POSITIONS
488	        handle_diagnostic_positions_for_json_value(*object_element);
489	#endif
490	
491	        return object_element;
492	    }
493	
494	    /// the parsed JSON value
495	    BasicJsonType& root;
496	    /// stack to model hierarchy of values
497	    std::vector<BasicJsonType*> ref_stack {};
498	    /// helper to hold the reference for the next object element
499	    BasicJsonType* object_element = nullptr;
500	    /// whether a syntax error occurred
501	    bool errored = false;
502	    /// whether to throw exceptions in case of errors
503	    const bool allow_exceptions = true;
504	    /// the lexer reference to obtain the current position
505	    lexer_t* m_lexer_ref = nullptr;
506	};
