508	template<typename BasicJsonType, typename InputAdapterType>
509	class json_sax_dom_callback_parser
510	{
511	  public:
512	    using number_integer_t = typename BasicJsonType::number_integer_t;
513	    using number_unsigned_t = typename BasicJsonType::number_unsigned_t;
514	    using number_float_t = typename BasicJsonType::number_float_t;
515	    using string_t = typename BasicJsonType::string_t;
516	    using binary_t = typename BasicJsonType::binary_t;
517	    using parser_callback_t = typename BasicJsonType::parser_callback_t;
518	    using parse_event_t = typename BasicJsonType::parse_event_t;
519	    using lexer_t = lexer<BasicJsonType, InputAdapterType>;
520	
521	    json_sax_dom_callback_parser(BasicJsonType& r,
522	                                 parser_callback_t cb,
523	                                 const bool allow_exceptions_ = true,
524	                                 lexer_t* lexer_ = nullptr)
525	        : root(r), callback(std::move(cb)), allow_exceptions(allow_exceptions_), m_lexer_ref(lexer_)
526	    {
527	        keep_stack.push_back(true);
528	    }
529	
530	    // make class move-only
531	    json_sax_dom_callback_parser(const json_sax_dom_callback_parser&) = delete;
532	    json_sax_dom_callback_parser(json_sax_dom_callback_parser&&) = default; // NOLINT(hicpp-noexcept-move,performance-noexcept-move-constructor)
533	    json_sax_dom_callback_parser& operator=(const json_sax_dom_callback_parser&) = delete;
534	    json_sax_dom_callback_parser& operator=(json_sax_dom_callback_parser&&) = default; // NOLINT(hicpp-noexcept-move,performance-noexcept-move-constructor)
535	    ~json_sax_dom_callback_parser() = default;
536	
537	    bool null()
538	    {
539	        handle_value(nullptr);
540	        return true;
541	    }
542	
543	    bool boolean(bool val)
544	    {
545	        handle_value(val);
546	        return true;
547	    }
548	
549	    bool number_integer(number_integer_t val)
550	    {
551	        handle_value(val);
552	        return true;
553	    }
554	
555	    bool number_unsigned(number_unsigned_t val)
556	    {
557	        handle_value(val);
558	        return true;
559	    }
560	
561	    bool number_float(number_float_t val, const string_t& /*unused*/)
562	    {
563	        handle_value(val);
564	        return true;
565	    }
566	
567	    bool string(string_t& val)
568	    {
569	        // json_sax documents that the passed value may be moved from,
570	        // so hand the buffer over instead of copying it
571	        handle_value(std::move(val));
572	        return true;
573	    }
574	
575	    bool binary(binary_t& val)
576	    {
577	        // json_sax documents that the passed value may be moved from,
578	        // so hand the buffer over instead of copying it
579	        handle_value(std::move(val));
580	        return true;
581	    }
582	
583	    bool start_object(std::size_t len)
584	    {
585	        // check callback for object start
586	        const bool keep = callback(static_cast<int>(ref_stack.size()), parse_event_t::object_start, discarded);
587	        keep_stack.push_back(keep);
588	
589	        // the key this object will be stored under, read before handle_value()
590	        // may consume it; kept in lockstep with ref_stack so end_object() can
591	        // find the object in its parent again
592	        container_key_stack.push_back(current_key());
593	
594	        auto val = handle_value(BasicJsonType::value_t::object, true);
595	        ref_stack.push_back(val.second);
596	
597	        if (ref_stack.back())
598	        {
599	
600	#if JSON_DIAGNOSTIC_POSITIONS
601	            // Manually set the start position of the object here.
602	            // Ensure this is after the call to handle_value to ensure correct start position.
603	            if (m_lexer_ref)
604	            {
605	                // Lexer has read the first character of the object, so
606	                // subtract 1 from the position to get the correct start position.
607	                ref_stack.back()->start_position = m_lexer_ref->get_position() - 1;
608	            }
609	#endif
610	
611	            // check object limit
612	            if (JSON_HEDLEY_UNLIKELY(len != detail::unknown_size() && len > ref_stack.back()->max_size()))
613	            {
614	                return parse_error(0, "", out_of_range::create(408, concat("excessive object size: ", std::to_string(len)), ref_stack.back()));
615	            }
616	        }
617	        return true;
618	    }
619	
620	    bool key(string_t& val)
621	    {
622	        BasicJsonType k = BasicJsonType(val);
623	
624	        // check callback for the key
625	        const bool keep = callback(static_cast<int>(ref_stack.size()), parse_event_t::key, k);
626	        key_keep_stack.push_back(keep);
627	        // remember the key so a rejected value can be erased without searching
628	        // the object for it (kept in lockstep with key_keep_stack)
629	        key_stack.push_back(val);
630	
631	        // add discarded value at the given key and store the reference for later
632	        if (keep && ref_stack.back())
633	        {
634	            auto& obj = *ref_stack.back()->m_data.m_value.object;
635	            const auto it = obj.find(val);
636	            if (it != obj.end())
637	            {
638	                // this is a duplicate key (legal in JSON); remember its
639	                // current value so it can be restored later if the new
640	                // value is rejected by the callback, instead of being
641	                // erased together with the discarded placeholder
642	                duplicate_key_stash.emplace_back(&(it->second), it->second);
643	            }
644	            object_element = &(obj[val] = discarded);
645	        }
646	
647	        return true;
648	    }
649	
650	    bool end_object()
651	    {
652	        if (ref_stack.back())
653	        {
654	            if (!callback(static_cast<int>(ref_stack.size()) - 1, parse_event_t::object_end, *ref_stack.back()))
655	            {
656	                // discard object, unless this slot holds a duplicate key's
657	                // previous value pending restoration, in which case that
658	                // value is restored instead of being discarded
659	                if (!resolve_duplicate_key_stash(ref_stack.back(), true))
660	                {
661	                    *ref_stack.back() = discarded;
662	
663	#if JSON_DIAGNOSTIC_POSITIONS
664	                    // Set start/end positions for discarded object.
665	                    handle_diagnostic_positions_for_json_value(*ref_stack.back());
666	#endif
667	                }
668	            }
669	            else
670	            {
671	
672	#if JSON_DIAGNOSTIC_POSITIONS
673	                if (m_lexer_ref)
674	                {
675	                    // Lexer's position is past the closing brace, so set that as the end position.
676	                    ref_stack.back()->end_position = m_lexer_ref->get_position();
677	                }
678	#endif
679	
680	                ref_stack.back()->set_parents();
681	                // this object is finally, definitively kept; drop any
682	                // pending duplicate-key stash entry for its slot since it
683	                // can no longer be restored
684	                resolve_duplicate_key_stash(ref_stack.back(), false);
685	            }
686	        }
687	
688	        JSON_ASSERT(!ref_stack.empty());
689	        JSON_ASSERT(!keep_stack.empty());
690	        JSON_ASSERT(!container_key_stack.empty());
691	        ref_stack.pop_back();
692	        keep_stack.pop_back();
693	        const string_t object_key = std::move(container_key_stack.back());
694	        container_key_stack.pop_back();
695	
696	        if (!ref_stack.empty() && ref_stack.back() && ref_stack.back()->is_structured())
697	        {
698	            // remove discarded value
699	            remove_discarded_value(*ref_stack.back(), object_key);
700	        }
701	
702	        return true;
703	    }
704	
705	    bool start_array(std::size_t len)
706	    {
707	        const bool keep = callback(static_cast<int>(ref_stack.size()), parse_event_t::array_start, discarded);
708	        keep_stack.push_back(keep);
709	
710	        // see start_object()
711	        container_key_stack.push_back(current_key());
712	
713	        auto val = handle_value(BasicJsonType::value_t::array, true);
714	        ref_stack.push_back(val.second);
715	
716	        if (ref_stack.back())
717	        {
718	
719	#if JSON_DIAGNOSTIC_POSITIONS
720	            // Manually set the start position of the array here.
721	            // Ensure this is after the call to handle_value to ensure correct start position.
722	            if (m_lexer_ref)
723	            {
724	                // Lexer has read the first character of the array, so
725	                // subtract 1 from the position to get the correct start position.
726	                ref_stack.back()->start_position = m_lexer_ref->get_position() - 1;
727	            }
728	#endif
729	
730	            // check array limit
731	            if (JSON_HEDLEY_UNLIKELY(len != detail::unknown_size() && len > ref_stack.back()->max_size()))
732	            {
733	                return parse_error(0, "", out_of_range::create(408, concat("excessive array size: ", std::to_string(len)), ref_stack.back()));
734	            }
735	
736	            if (len != detail::unknown_size())
737	            {
738	                reserve_array(*ref_stack.back()->m_data.m_value.array, len, priority_tag<1> {});
739	            }
740	        }
741	
742	        return true;
743	    }
744	
745	    bool end_array()
746	    {
747	        bool keep = true;
748	        const bool stored = ref_stack.back() != nullptr;
749	
750	        if (stored)
751	        {
752	            keep = callback(static_cast<int>(ref_stack.size()) - 1, parse_event_t::array_end, *ref_stack.back());
753	            if (keep)
754	            {
755	
756	#if JSON_DIAGNOSTIC_POSITIONS
757	                if (m_lexer_ref)
758	                {
